CREATE DATABASE IF NOT EXISTS siteforge_cms CHARACTER SET utf8mb4;
USE siteforge_cms;
CREATE TABLE site_users(user_id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(80) NOT NULL, username VARCHAR(40) NOT NULL UNIQUE, pass_hash VARCHAR(255) NOT NULL, role ENUM('admin','manager','accountant','supervisor') NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE build_projects(project_id INT AUTO_INCREMENT PRIMARY KEY, title VARCHAR(120) NOT NULL, location VARCHAR(120), start_date DATE, due_date DATE, budget DECIMAL(14,2) NOT NULL CHECK(budget>=0), status ENUM('planned','active','completed','archived') DEFAULT 'active', progress_pct TINYINT DEFAULT 0 CHECK(progress_pct BETWEEN 0 AND 100), manager_id INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(manager_id) REFERENCES site_users(user_id), INDEX(status));
CREATE TABLE labour_force(worker_id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(80) NOT NULL, phone VARCHAR(20), trade VARCHAR(40), daily_wage DECIMAL(10,2) NOT NULL CHECK(daily_wage>=0), project_id INT NULL, status ENUM('active','inactive') DEFAULT 'active', FOREIGN KEY(project_id) REFERENCES build_projects(project_id));
CREATE TABLE attendance_log(att_id INT AUTO_INCREMENT PRIMARY KEY, worker_id INT NOT NULL, work_date DATE NOT NULL, status ENUM('present','half','absent','leave') NOT NULL, overtime_hrs DECIMAL(4,1) DEFAULT 0 CHECK(overtime_hrs>=0), UNIQUE(worker_id,work_date), FOREIGN KEY(worker_id) REFERENCES labour_force(worker_id));
CREATE TABLE vendors(vendor_id INT AUTO_INCREMENT PRIMARY KEY, vendor_name VARCHAR(100) NOT NULL, phone VARCHAR(20), email VARCHAR(100));
CREATE TABLE stock_items(item_id INT AUTO_INCREMENT PRIMARY KEY, item_name VARCHAR(80) NOT NULL UNIQUE, unit VARCHAR(15) NOT NULL, qty_on_hand DECIMAL(12,2) NOT NULL DEFAULT 0 CHECK(qty_on_hand>=0), reorder_level DECIMAL(12,2) DEFAULT 0, vendor_id INT NULL, FOREIGN KEY(vendor_id) REFERENCES vendors(vendor_id));
CREATE TABLE stock_ledger(txn_id INT AUTO_INCREMENT PRIMARY KEY, item_id INT NOT NULL, project_id INT NULL, txn_type ENUM('purchase','issue','return','adjust') NOT NULL, qty DECIMAL(12,2) NOT NULL CHECK(qty>0), unit_cost DECIMAL(10,2) DEFAULT 0 CHECK(unit_cost>=0), txn_date DATETIME DEFAULT CURRENT_TIMESTAMP, user_id INT NULL, FOREIGN KEY(item_id) REFERENCES stock_items(item_id), FOREIGN KEY(project_id) REFERENCES build_projects(project_id));
CREATE TABLE cost_entries(cost_id INT AUTO_INCREMENT PRIMARY KEY, project_id INT NOT NULL, category ENUM('material','labour','equipment','transport','misc') NOT NULL, amount DECIMAL(14,2) NOT NULL CHECK(amount>=0), cost_date DATE NOT NULL, description VARCHAR(200), FOREIGN KEY(project_id) REFERENCES build_projects(project_id));
CREATE TABLE payroll_runs(run_id INT AUTO_INCREMENT PRIMARY KEY, worker_id INT NOT NULL, pay_month CHAR(7) NOT NULL, days_worked DECIMAL(5,1), overtime_hrs DECIMAL(6,1), gross_pay DECIMAL(12,2), paid ENUM('no','yes') DEFAULT 'no', UNIQUE(worker_id,pay_month), FOREIGN KEY(worker_id) REFERENCES labour_force(worker_id));
CREATE TABLE equipment_assets(equip_id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL, next_service DATE, condition_status ENUM('good','needs_repair','out_of_service') DEFAULT 'good');
CREATE TABLE safety_checks(check_id INT AUTO_INCREMENT PRIMARY KEY, project_id INT NOT NULL, check_date DATE NOT NULL, inspector VARCHAR(80), findings VARCHAR(300), result ENUM('pass','fail') NOT NULL, FOREIGN KEY(project_id) REFERENCES build_projects(project_id));
CREATE TABLE incident_reports(incident_id INT AUTO_INCREMENT PRIMARY KEY, project_id INT NOT NULL, incident_date DATE NOT NULL, severity ENUM('minor','major','fatal') NOT NULL, description VARCHAR(300), resolved ENUM('open','closed') DEFAULT 'open', FOREIGN KEY(project_id) REFERENCES build_projects(project_id));
CREATE TABLE progress_logs(log_id INT AUTO_INCREMENT PRIMARY KEY, project_id INT NOT NULL, log_date DATE NOT NULL, work_done VARCHAR(300) NOT NULL, workers_count INT DEFAULT 0, hours DECIMAL(5,1) DEFAULT 0, delay_reason VARCHAR(200), FOREIGN KEY(project_id) REFERENCES build_projects(project_id));
CREATE TABLE audit_trail(audit_id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NULL, action VARCHAR(200) NOT NULL, at_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE VIEW v_project_spend AS SELECT p.project_id,p.title,p.budget,COALESCE(SUM(c.amount),0) spent, ROUND(COALESCE(SUM(c.amount),0)/NULLIF(p.budget,0)*100,1) used_pct FROM build_projects p LEFT JOIN cost_entries c ON c.project_id=p.project_id GROUP BY p.project_id;

